package com.benchmark.supplychain.billing;

import lombok.Builder;
import lombok.Data;
import java.math.BigDecimal;

/**
 * THE N+1 REPORT SCENARIO
 *
 * In the monolith, this report is generated by reading 4 modules directly:
 *   Order → revenue
 *   Carrier → shipping cost
 *   Customs → duties/taxes
 *   Route → fuel estimate
 * All in a single @Transactional read — zero HTTP calls.
 *
 * In microservices, generating this would require:
 *   1. HTTP GET order-service/orders/{id}
 *   2. HTTP GET carrier-service/carriers/order/{id}
 *   3. HTTP GET customs-service/customs/order/{id}
 *   4. HTTP GET route-service/routes/order/{id}
 *   Then join the 4 JSON responses in memory.
 *   Each call can fail independently — 4 independent error states to handle.
 */
@Data
@Builder
public class ShipmentProfitabilityReport {
    private Long orderId;
    private String orderNumber;
    private String destinationCountry;

    // From Order module
    private BigDecimal revenue;
    private String currency;

    // From Carrier module
    private String carrierName;
    private BigDecimal shippingCost;

    // From Customs module (null for domestic)
    private BigDecimal dutiesAndTaxes;

    // From Route module
    private BigDecimal fuelCost;
    private BigDecimal distanceKm;

    // Calculated
    private BigDecimal totalCost;
    private BigDecimal grossProfit;
    private BigDecimal marginPercent;
}
